rows = json.load(open(sys.argv[1] + "/kub_rows.json"))
SRC = "Kubiak, P. J. (2009). Fire responses of bushland plants after the January 1994 wildfires in northern Sydney. Cunninghamia, 11(1), 131-165."
FN = "Kubiak Cunn 2009"
LCR, NL = "Lane Cove River valley", "Narrabeen Lagoon catchment area"
CODEDEF = {"R": "majority of adult plants resprouted", "K": "majority of adult plants killed", "r": "a small proportion resprouted",
           "k": "a small proportion killed", "pR": "probably resprouted", "pK": "probably killed", "?R": "possibly resprouted", "?K": "possibly killed"}
def name(n):
    notes = []; printed = n; status = ""
    if n.startswith("(*?)"): n = n[4:]; notes.append("exotic status printed as '(*?)'")
    elif n.startswith("*"): n = n[1:]; status = "exotic"
    n = n.replace("–", "-")
    m = re.match(r"(.*?) \(syn\. (.*)\)$", n)
    if m: n = m.group(1); notes.append(f"printed with synonym '{m.group(2)}'")
    n2 = re.sub(r" \((s\.lat\.|s\.str\.)\)", "", n).replace("?", "").replace("“", "").replace("”", "")
    g, rest = n2.split(" ", 1)
    sub = ""
    m = re.match(r"(.+?) ((?:subsp\.|var\.|cv\.) .+)$", rest)
    if m: rest, sub = m.group(1), m.group(2)
    if rest == "(hybrid)": rest = "hybrid"
    pr = printed.lstrip("*") if status else printed
    if n2 != n or pr != n.replace("-", "–") and "(*?)" not in printed and "syn." not in printed:
        if n2 != n: notes.append(f"name printed as '{pr}'")
    return g, rest, sub, status, notes
def num(x): return x
def conv(v, unit):  # v number string, to years
    if unit == "y": return v, None
    y = round(float(v) / 52, 3)
    s = ("%.3f" % y).rstrip("0").rstrip(".")
    return s, v
def parse_time(raw):
    """return (value, unit, extra_note) for the first-time value in cell; None if no time."""
    s = raw.replace("<u>", "").replace("</u>", "")
    bold = re.findall(r"\*\*(.+?)\*\*", s)
    s0 = s
    notes = []
    m = re.match(r"^(c\. ?)?(\?)?(\d+(?:\.\d+)?)(\+)?\s*(?:[-–]\s*(\d+(?:\.\d+)?)(\+)?)?\s*([wy])", s.replace("**", ""))
    if s.startswith("Less than"):
        m2 = re.match(r"Less than (\d+) year", s); return "<" + m2.group(1), "y", [f"printed '{raw}'"]
    if s.startswith("At least"):
        m2 = re.match(r"At least (\d+) years", s); return ">" + m2.group(1), "y", [f"printed '{raw}'"]
    if s.startswith("c.?"):
        m2 = re.match(r"c\.\?(\d+)[-–](\d+)y\?", s); return f"{m2.group(1)}-{m2.group(2)}", "y", [f"printed '{raw}' (approximate, uncertain)"]
    if not m:
        m3 = re.match(r"^(\d+),\*\*(\d+)w\*\*", s)
        if m3: return m3.group(1), "w", [f"printed '{raw}': first value assumed weeks; bold = sizable proportion of population flowering"]
        return None
    lo, plus1, hi, plus2, unit = m.group(3), m.group(4), m.group(5), m.group(6), m.group(7)
    v = lo if not hi else f"{lo}-{hi}"
    if m.group(1) or m.group(2) or plus1 or plus2 or s.replace("**", "") != m.group(0).strip() or bold:
        notes.append(f"printed '{raw.replace('<u>', '').replace('</u>', '')}'")
    if m.group(1): notes.append("c. = approximately")
    if plus1 or plus2: notes.append("'+' = or more")
    if bold: notes.append("bold = sizable proportion of population flowering")
    return v, unit, notes
def fixed(col, raw, label):
    p = parse_time(raw)
