    if unit == "w" and not v.startswith(("<", ">")):
        parts = v.split("-")
        cv = "-".join(conv(x, "w")[0] for x in parts)
        notes = notes + [f"{col} converted from {v} weeks"]
        v = cv
    elif unit == "w":
        cv = v[0] + conv(v[1:], "w")[0]; notes = notes + [f"{col} converted from {v} weeks"]; v = cv
    return v, [f"{label}: " + "; ".join(notes)] if notes else []
out = []; skipped = []
