    c = r["cells"]; fam, nm, peak, lcr, nl, seedl, flr, fls, frr, frs, pjp, sjp = c
    g, sp, sub, status, nnotes = name(nm)
    base = dict(Genus=g, Species=sp, subsp=sub, native_status=status, Family=fam, Fire_type="wildfire",
