    common = [f"Appendix 1, p. {r['page']}"] + nnotes
    # fire response codes
    def code(x):
        x = x.strip()
        if not x or len(x) > 12: return "", ([f"fire response cell: '{x}'"] if x else [])
        if x.startswith("K;r"): return "obligate", [f"fire response printed '{x}' (r after moderate intensity fire at 71 weeks)"]
        x2 = re.sub(r"\s*([?/;,()])\s*", r"\1", x)
        if x2 == "R": return "resprouter", ["fire response 'R' = majority of adult plants resprouted"]
        if x2 == "K": return "obligate", ["fire response 'K' = majority of adult plants killed"]
        parts = re.split(r"/", x2)
        d = "; ".join(f"'{p}' = {CODEDEF[p.lstrip('?') if p.startswith('?') and p[1:] in ('r','k') else p]}" if (p in CODEDEF or p[1:] in ('r','k')) else p for p in parts)
        return x2, [f"fire response '{x2}': {d}"]
    sites = []
    for cell, site in [(lcr, "LCR"), (nl, "NL")]:
        cd, cn = code(cell)
        if cell.strip() and len(cell.strip()) > 12 and site == "NL" and cell.startswith("The host"):
            common.append(f"NL note: '{cell}'"); continue
        if cell.strip() and len(cell.strip()) > 12:
            common.append(f"{site} cell printed '{cell}'")
            if cell.startswith("R(1)m.i.f"): continue
        if cd: sites.append((site, cd, cn))
    # times
    t = {}; tn = []
    bridge = ("<u>" in flr)
    if bridge:
        tn.append(f"first flowering printed '{flr.replace('<u>','').replace('</u>','')}' (underlined: unclear whether from seed or resprout; not used)")
    else:
        if flr:
            if "m.i.f" in flr or flr.startswith(("Resprouted", "Leaves", "Note")):
                tn.append(f"first flowering Resp printed '{flr}' (not used)")
            else:
                x = fixed("Time to first flower production resprout_repr3a", flr, "first flowering Resp")
                if x: t["Time to first flower production resprout_repr3a"] = x[0]; tn += x[1]
                else: tn.append(f"first flowering Resp printed '{flr}' (not used)")
        if fls:
            x = fixed("Age at first flower production from seed_repr3", fls, "first flowering Seed")
            if x: t["Age at first flower production from seed_repr3"] = x[0]; tn += x[1]
            else: tn.append(f"first flowering Seed printed '{fls}' (not used)")
    if pjp:
        x = fixed("primary_juvenile_period", pjp, "primary juvenile period")
        t["primary_juvenile_period"] = x[0]; tn += x[1]
    if sjp:
        p = parse_time(sjp)
        v, unit, nn = p
        t["secondary_juvenile_period"] = v; t["Time_unit"] = {"w": "weeks", "y": "years"}[unit]
        if nn: tn.append("secondary juvenile period: " + "; ".join(nn))
    for lab, v in [("first fruiting Resp", frr), ("first fruiting Seed", frs)]:
        if v and not (lab.endswith("Seed") and "<u>" in v): tn.append(f"{lab} '{v.replace('<u>','').replace('</u>','')}'" + (" (underlined: unclear whether from seed or resprout)" if "<u>" in v else ""))
    if seedl: tn.append(f"seedlings first observed '{seedl}'")
    if peak: tn.append(f"peaks: '{peak}'")
    if any(k in t for k in ("primary_juvenile_period", "secondary_juvenile_period")) or any(" (shd)" in x or "grn" in x for x in tn):
        pass
    if t:
        if any("(shd)" in v or "grn" in v or "fruit" in v for v in (pjp, sjp)):
            tn.append("juvenile period values carry fruiting qualifiers: grn = green fruit, (shd) = shedding seed or spores, ri = ripe fruit")
    sitename = {"LCR": dict(Latitude="-33.75", Longitude="151.0833"), "NL": dict(Location_name=NL)}
    fire = {"LCR": "Lane Cove River fire began 6 January 1994", "NL": "Narrabeen Lagoon fire began 8 January 1994"}
    gen = "season derived from date (January 1994); fires generally of apparently high intensity, large proportion with 100% canopy scorch"
    def mk(site_kw, resp, notes):
        d = dict(base); d.update(site_kw)
        if resp: d["fire_response categorical_surv1"] = resp
        d["Notes"] = "; ".join(notes); return d
    if t and len(sites) == 2:
        for s, cd, cn in sites:
            out.append(mk(sitename[s], cd, common + cn + [fire[s], gen]))
        d = mk(dict(Location_name=f"{LCR} / {NL}"), "", common + tn + ["time values not split by catchment; species recorded in both", gen])
        d.update(t); out.append(d)
    elif t and len(sites) == 1:
        s, cd, cn = sites[0]
        d = mk(sitename[s], cd, common + cn + tn + [fire[s], gen]); d.update(t); out.append(d)
    elif t:
        d = mk(dict(Location_name=f"{LCR} / {NL}"), "", common + tn + ["no fire response code; catchment not stated", gen]); d.update(t); out.append(d)
    elif sites:
        for s, cd, cn in sites:
            out.append(mk(sitename[s], cd, common + cn + tn + [fire[s], gen]))
    else:
        skipped.append((r["line"], nm))
json.dump(out, open(sys.argv[1] + "/kub_out.json", "w"))
print(len(out), "rows; skipped", len(skipped)); [print(x) for x in skipped]
EOF
