S=/tmp/claude-1000/-home-jess-Documents-primary-juvenile-meta-analysis/ffba97e0-c836-42ae-9cb5-326b81e8442b/scratchpad; cat > $S/nsw_build.py <<'EOF'
import json, re, sys, random
sys.path.insert(0, sys.argv[1]); from helper import append
d = json.load(open(sys.argv[1] + "/nsw.json"))
FN = "nswfrrd_v1.3a_pdfvers_sppdata"
out = []
for x in d:
    r, v = x["r"], x["v"]
    nm = re.sub(r"- (?=[a-z])", "-", r[0])
    g, rest = nm.split(" ", 1)
    sub = ""
    m = re.match(r"(.+?) ((?:subsp\.?|var\.?|forma|f\.|nothosubsp\.) .+)$", rest)
    if m and not rest.startswith("sp."):
        rest, sub = m.group(1), m.group(2)
        sub = re.sub(r"\bsubsp\.? ", "subsp. ", sub); sub = re.sub(r"\bvar\.? ", "var. ", sub); sub = re.sub(r"\bforma ", "f. ", sub)
    notes = [f"PDF p. {x['page']}-{x['page'] + 1}", "fire response code as printed; codes not defined in document"]
    if nm != r[0]: notes.append(f"name printed as '{r[0]}'")
    if v[4]: notes.append(f"Primary juvenile {v[4]} (unit not stated)")
    if v[5]: notes.append(f"Secondary juvenile period {v[5]} (unit not stated)")
    if r[4]: notes.append(f"comments on regeneration: {r[4]}")
    st = ""
    if v[9] == "Exotic": st = "exotic"; notes.append("native status from column 'Distribution: NSW' = Exotic")
    notes.append("compiled species database; no study site or fire; no citation printed in document")
    out.append(dict(Genus=g, Species=rest, subsp=sub, native_status=st, Family=r[2],
        **{"fire_response categorical_surv1": r[3]}, Notes="; ".join(notes), Source=FN, File_name=FN))
random.seed(3)
for i in random.sample(range(len(out)), 3):
    print("SRC:", d[i]["r"][:5], d[i]["v"][:6], d[i]["v"][9]); print("ROW:", {k: v for k, v in out[i].items() if v and k not in ("Source", "File_name")}); print()
for o in out:
    if o["subsp"] and not re.match(r"(subsp\.|var\.|f\.|nothosubsp\.) ", o["subsp"]): print("SUB?", o["subsp"])
print([ (o["Genus"], o["Species"], o["subsp"]) for o in out if o["Species"].startswith("sp") or "-" in o["Species"] or " " in o["subsp"].split(" ",1)[1:][0] if o["subsp"]][:40])
if len(sys.argv) > 2: print(append(out))
EOF
python3 $S/nsw_build.py $S

